let name = String::from("Sam");
let other = name; // ownership of the String moves to `other`

println!("{}", name); // compile error: `name`'s value was moved into `other`

use std::thread;

fn send_to_thread<T: Send>(value: T) {
    thread::spawn(move || {
        // `value` is now owned by the new thread; the compiler only
        // accepts this call if T is marked Send.
        drop(value);
    });
}

let x = 5;
let y = x;           // i32 is Copy: this copies the value

println!("{} {}", x, y); // both fine — x was never invalidated

let s1 = String::from("hi");
let s2 = s1.clone(); // explicit, visible deep copy

println!("{} {}", s1, s2); // both fine

struct Ticket {
    label: String,
}

impl Drop for Ticket {
    fn drop(&mut self) {
        println!("tearing up ticket: {}", self.label);
    }
}

fn main() {
    let a = Ticket { label: String::from("A") };
    let b = Ticket { label: String::from("B") };
    println!("holding both tickets");
} // b is dropped first, then a — reverse declaration order
